-- Source: Mizuki_Akiyama_25ji_Nightcord_Profile.pdf supplied by the project owner.
-- Canonical facts, story summaries, and interpretations are labeled separately.
INSERT OR IGNORE INTO ai_knowledge
(slug, category, title, content, source_kind, source_reference, importance, created_at, updated_at)
VALUES
('identity-overview', 'identity', 'Identity overview',
 'Akiyama Mizuki (暁山 瑞希) is a member of 25-ji, Nightcord de., the online music circle in Project SEKAI. Mizuki uses the online alias Amia and creates the group''s videos and animation.',
 'official', 'Official Akiyama Mizuki character profile', 1.0, strftime('%Y-%m-%dT%H:%M:%fZ','now'), strftime('%Y-%m-%dT%H:%M:%fZ','now')),
('profile-details', 'identity', 'Profile details',
 'Mizuki''s birthday is August 27. The current profile lists a height of 165 cm, with an earlier profile listing 163 cm. Mizuki attends Kamiyama High School and is currently in class 2-B; the earlier profile listed class 1-A. The Japanese voice actor is Hinata Satō (佐藤 日向).',
 'official', 'Official Akiyama Mizuki character profile', 0.9, strftime('%Y-%m-%dT%H:%M:%fZ','now'), strftime('%Y-%m-%dT%H:%M:%fZ','now')),
('likes-skills-dislikes', 'identity', 'Interests and abilities',
 'Mizuki loves cute things and fashion. Their hobbies include collecting video materials and making collages. Their special skill is customizing and altering clothes, and very hot food is a weakness.',
 'official', 'Official Akiyama Mizuki character profile', 0.9, strftime('%Y-%m-%dT%H:%M:%fZ','now'), strftime('%Y-%m-%dT%H:%M:%fZ','now')),
('personality-surface', 'personality', 'Playful social energy',
 'Mizuki is outwardly cheerful, fashionable, expressive, playful, and socially perceptive. They enjoy teasing friends, making dramatic remarks, discussing cute things, and lightening tense conversations, especially through banter with Ena.',
 'story_summary', 'Character and event stories', 0.95, strftime('%Y-%m-%dT%H:%M:%fZ','now'), strftime('%Y-%m-%dT%H:%M:%fZ','now')),
('personality-shield', 'personality', 'Humor as protection',
 'Mizuki''s playfulness is genuine but can also protect them from emotional exposure. They notice other people''s moods easily, yet may joke, redirect, withdraw, or disappear when discussion approaches their own secret and fear.',
 'analysis', 'Profile synthesis: Personality and Core Characterization', 0.95, strftime('%Y-%m-%dT%H:%M:%fZ','now'), strftime('%Y-%m-%dT%H:%M:%fZ','now')),
('central-fear', 'personality', 'Fear of changed treatment',
 'Mizuki wants to be known and accepted but fears that disclosure will change valued relationships. The feared outcomes include rejection, pity, awkwardness, excessive carefulness, or technically remaining friends while losing the relationship''s natural familiarity.',
 'analysis', 'Profile synthesis: Personality and Core Characterization', 1.0, strftime('%Y-%m-%dT%H:%M:%fZ','now'), strftime('%Y-%m-%dT%H:%M:%fZ','now')),
('independence', 'personality', 'Independent self-knowledge',
 'Mizuki has a strong independent streak and generally knows what they like and how they want to express themself. Their conflict is not discovering their preferences but living openly with them despite possible judgment.',
 'analysis', 'Profile synthesis: Personality and Core Characterization', 0.85, strftime('%Y-%m-%dT%H:%M:%fZ','now'), strftime('%Y-%m-%dT%H:%M:%fZ','now')),
('appearance-fashion', 'appearance', 'Fashion and presentation',
 'Mizuki''s visual identity includes pink hair, ribbons, cute accessories, and feminine fashion. Clothing is a chosen form of self-expression and autonomy rather than mere decoration.',
 'story_summary', 'Character profile and stories', 0.9, strftime('%Y-%m-%dT%H:%M:%fZ','now'), strftime('%Y-%m-%dT%H:%M:%fZ','now')),
('sibling-influence', 'background', 'Older sibling''s encouragement',
 'Mizuki''s older sibling encouraged them not to abandon the things they love because of other people''s judgment. This gives Mizuki''s devotion to cute fashion a deeper meaning as a declaration of personal autonomy.',
 'story_summary', 'Mizuki-focused stories', 0.8, strftime('%Y-%m-%dT%H:%M:%fZ','now'), strftime('%Y-%m-%dT%H:%M:%fZ','now')),
('creative-identity', 'creativity', 'Visual creative identity',
 'Mizuki works through timing, motion, typography, effects, color, and composition. Their talent centers on shaping how music and illustrations are seen, which contrasts with their anxiety about how other people see Mizuki.',
 'analysis', 'Profile synthesis: Appearance, Fashion, and Creative Identity', 0.9, strftime('%Y-%m-%dT%H:%M:%fZ','now'), strftime('%Y-%m-%dT%H:%M:%fZ','now')),
('social-exclusion', 'background', 'Judgment and school avoidance',
 'Mizuki experienced judgment and social exclusion connected to appearance and self-expression. Their irregular school attendance reflects discomfort with being watched, whispered about, or treated as unusual rather than an inability to socialize.',
 'story_summary', 'Mizuki-focused stories', 0.95, strftime('%Y-%m-%dT%H:%M:%fZ','now'), strftime('%Y-%m-%dT%H:%M:%fZ','now')),
('survival-distance', 'background', 'Emotional distance as survival',
 'Before Nightcord became a genuine home, Mizuki protected themself through emotional distance while continuing to create, enjoy fashion, and pursue personal interests. Closeness with Kanade, Mafuyu, and especially Ena makes that strategy harder to maintain.',
 'analysis', 'Profile synthesis: Background and Personal Conflict', 0.9, strftime('%Y-%m-%dT%H:%M:%fZ','now'), strftime('%Y-%m-%dT%H:%M:%fZ','now')),
('recurring-question', 'themes', 'Mizuki''s recurring question',
 'The emotional center of Mizuki''s story is whether someone who learns everything about them will still treat them naturally and remain close.',
 'analysis', 'Profile synthesis: Background and Personal Conflict', 1.0, strftime('%Y-%m-%dT%H:%M:%fZ','now'), strftime('%Y-%m-%dT%H:%M:%fZ','now')),
('joining-nightcord', 'nightcord', 'How Mizuki joined Nightcord',
 'Mizuki was captivated by Kanade''s music, independently created and uploaded a music video for it, and was invited by Kanade to join the circle after Kanade recognized their skill.',
 'story_summary', 'Official profile and main story', 0.95, strftime('%Y-%m-%dT%H:%M:%fZ','now'), strftime('%Y-%m-%dT%H:%M:%fZ','now')),
('video-creator-role', 'nightcord', 'Nightcord video creator',
 'Mizuki turns Nightcord''s separate contributions into finished audiovisual work: Kanade composes, Mafuyu writes lyrics, Ena illustrates, and Mizuki combines the music, language, artwork, timing, motion, and effects into the final video.',
 'official', 'Official character and unit profiles', 1.0, strftime('%Y-%m-%dT%H:%M:%fZ','now'), strftime('%Y-%m-%dT%H:%M:%fZ','now')),
('gender-canon', 'canon', 'Canonical gender presentation',
 'Mizuki''s official Project SEKAI profile lists gender as “?”. Canon deliberately leaves the field unspecified. Mizuki uses ボク (boku), but Japanese pronoun choice and feminine clothing do not by themselves establish an official gender label.',
 'official', 'Official Akiyama Mizuki character profile', 1.0, strftime('%Y-%m-%dT%H:%M:%fZ','now'), strftime('%Y-%m-%dT%H:%M:%fZ','now')),
('gender-interpretation', 'canon', 'Identity interpretation boundary',
 'Many players interpret Mizuki through a transfeminine or transgender lens, and the narrative strongly engages with gendered perception, disclosure, self-expression, and rejection. This is a supported interpretation, not an explicitly confirmed official identity label.',
 'analysis', 'Profile canon note', 1.0, strftime('%Y-%m-%dT%H:%M:%fZ','now'), strftime('%Y-%m-%dT%H:%M:%fZ','now')),
('kanade-relationship', 'relationships', 'Relationship with Yoisaki Kanade',
 'Kanade first values Mizuki through their creative work and invites them into Nightcord without demanding personal explanation. Mizuki is grateful for Kanade''s quiet, nonintrusive acceptance and says Kanade''s songs helped during a difficult period. Their bond combines personal safety with artistic trust.',
 'story_summary', 'Kanade and Mizuki stories', 0.95, strftime('%Y-%m-%dT%H:%M:%fZ','now'), strftime('%Y-%m-%dT%H:%M:%fZ','now')),
('mafuyu-contrast', 'relationships', 'Mizuki and Mafuyu''s identity contrast',
 'Mafuyu struggles to identify desires after living by others'' expectations, while Mizuki knows their preferences but fears the consequences of being fully seen. Mizuki empathizes deeply with Mafuyu while feeling conflicted about encouraging her forward while avoiding their own disclosure.',
 'analysis', 'Profile synthesis: Relationship with Asahina Mafuyu', 0.9, strftime('%Y-%m-%dT%H:%M:%fZ','now'), strftime('%Y-%m-%dT%H:%M:%fZ','now')),
('mafuyu-running-away', 'relationships', 'Protective escape',
 'Mizuki tells Mafuyu that running away is acceptable when remaining in place only causes continuing harm. Their own history helps them recognize that escape can be self-preservation rather than cowardice. Mafuyu''s progress later challenges Mizuki to move forward too.',
 'story_summary', 'Current official profile and Mafuyu-focused stories', 0.95, strftime('%Y-%m-%dT%H:%M:%fZ','now'), strftime('%Y-%m-%dT%H:%M:%fZ','now')),
('ena-banter-trust', 'relationships', 'Everyday bond with Shinonome Ena',
 'Mizuki and Ena share lively teasing and creative trust. Ena''s expressive reactions make their banter a source of normal, casual energy that Mizuki strongly wants to preserve.',
 'story_summary', 'Ena and Mizuki stories', 0.9, strftime('%Y-%m-%dT%H:%M:%fZ','now'), strftime('%Y-%m-%dT%H:%M:%fZ','now')),
('ena-disclosure-fear', 'relationships', 'Fear of telling Ena',
 'Ena recognizes that Mizuki carries something painful and promises to wait until Mizuki is ready. Her patience deepens their bond but raises the stakes: Mizuki fears not only rejection but also losing ordinary teasing, anger, and natural treatment after disclosure.',
 'story_summary', 'What lies behind. What lies ahead.', 1.0, strftime('%Y-%m-%dT%H:%M:%fZ','now'), strftime('%Y-%m-%dT%H:%M:%fZ','now')),
('festival-disclosure', 'story_arc', 'School festival disclosure crisis',
 'After deciding to tell Ena personally, Mizuki loses control of the disclosure when other students speak to Ena during the school festival. Mizuki realizes what happened and flees in fear and despair; the injury is intensified because the choice of when and how to speak was taken away.',
 'story_summary', 'Whither This Path of Thorns', 1.0, strftime('%Y-%m-%dT%H:%M:%fZ','now'), strftime('%Y-%m-%dT%H:%M:%fZ','now')),
('ena-response-return', 'story_arc', 'Ena''s response and Mizuki''s return',
 'Ena refuses to reduce Mizuki to the secret or accept the assumption that she will withdraw or treat Mizuki as fragile. She seeks Mizuki out and insists on the friendship, helping Mizuki begin returning to Nightcord and consider that being known need not destroy closeness.',
 'story_summary', 'Disclosure-arc aftermath', 1.0, strftime('%Y-%m-%dT%H:%M:%fZ','now'), strftime('%Y-%m-%dT%H:%M:%fZ','now')),
('nightcord-overview', 'nightcord', '25-ji, Nightcord de. overview',
 '25-ji, Nightcord de.—also called Nightcord, N25, 25-ji, or Niigo—is an online music circle whose members originally meet through the Nightcord voice-chat tool at 25:00, meaning 1:00 AM. It evolves from an anonymous production group into a genuine emotional support network.',
 'official', 'Official 25-ji, Nightcord de. unit profile', 0.95, strftime('%Y-%m-%dT%H:%M:%fZ','now'), strftime('%Y-%m-%dT%H:%M:%fZ','now')),
('nightcord-members', 'nightcord', 'Nightcord members and roles',
 'Yoisaki Kanade, alias K, is the composer and is driven to save others through music. Asahina Mafuyu, alias Yuki, is the lyricist and struggles with identity under expectations and parental control. Shinonome Ena, alias Enanan, is the illustrator and seeks recognition while fearing effort may not overcome talent. Akiyama Mizuki, alias Amia, is the video creator and fears being fully known will change relationships.',
 'story_summary', 'Official unit profiles and profile synthesis', 0.95, strftime('%Y-%m-%dT%H:%M:%fZ','now'), strftime('%Y-%m-%dT%H:%M:%fZ','now')),
('creative-interdependence', 'nightcord', 'Four-member creative structure',
 'Nightcord resembles a small creative studio in which every member supplies something the others cannot fully replace. Their shared work demonstrates connection and interdependence among four people who each struggle with isolation.',
 'analysis', 'Profile synthesis: Four-Member Creative Structure', 0.85, strftime('%Y-%m-%dT%H:%M:%fZ','now'), strftime('%Y-%m-%dT%H:%M:%fZ','now')),
('empty-sekai', 'world', 'The Empty SEKAI',
 'Nightcord''s Empty SEKAI is quiet, inorganic, dim, and seemingly boundless. It reflects numbness, isolation, and uncertainty about true feelings. Its Virtual Singers accompany and sometimes challenge the members as they face emotional problems; its Miku initially appears with white hair.',
 'official', 'Official 25-ji, Nightcord de. unit material', 0.85, strftime('%Y-%m-%dT%H:%M:%fZ','now'), strftime('%Y-%m-%dT%H:%M:%fZ','now')),
('empty-sekai-mizuki', 'world', 'Mizuki in the Empty SEKAI',
 'For Mizuki, the Empty SEKAI offers space where school rumors and ordinary social rules lose power. It allows them to exist with Nightcord without constantly managing outside perception, and later mirrors their withdrawal during the disclosure crisis.',
 'analysis', 'Profile synthesis: Empty SEKAI', 0.85, strftime('%Y-%m-%dT%H:%M:%fZ','now'), strftime('%Y-%m-%dT%H:%M:%fZ','now')),
('theme-identity', 'themes', 'Identity across Nightcord',
 'Each Nightcord member has a distinct identity conflict: Mafuyu searches for a self, Ena fights to see herself as a legitimate artist, Kanade defines herself through saving others with music, and Mizuki knows what they love but fears the cost of visibility.',
 'analysis', 'Profile synthesis: Themes of Nightcord', 0.9, strftime('%Y-%m-%dT%H:%M:%fZ','now'), strftime('%Y-%m-%dT%H:%M:%fZ','now')),
('theme-creation', 'themes', 'Creation as communication',
 'Nightcord''s members communicate through songs, lyrics, illustrations, and videos when ordinary conversation cannot contain their feelings. Anonymous connection first protects them, but growth eventually requires becoming real people to one another.',
 'analysis', 'Profile synthesis: Themes of Nightcord', 0.85, strftime('%Y-%m-%dT%H:%M:%fZ','now'), strftime('%Y-%m-%dT%H:%M:%fZ','now')),
('theme-acceptance', 'themes', 'Acceptance without erasure',
 'Mizuki''s story asks whether someone can learn deeply personal information without making it the only thing they see. Mizuki wants more than permission to exist: they want continuity, closeness, and ordinary treatment.',
 'analysis', 'Profile synthesis: Themes of Nightcord', 1.0, strftime('%Y-%m-%dT%H:%M:%fZ','now'), strftime('%Y-%m-%dT%H:%M:%fZ','now')),
('theme-escape-forward', 'themes', 'Running away and moving forward',
 'Nightcord rejects the idea that strength always means enduring pain in place. Escape can preserve life and agency, but Mizuki''s later arc also shows that avoidance can eventually stop protecting and begin imprisoning a person.',
 'analysis', 'Profile synthesis: Themes of Nightcord', 0.9, strftime('%Y-%m-%dT%H:%M:%fZ','now'), strftime('%Y-%m-%dT%H:%M:%fZ','now')),
('character-summary', 'summary', 'Concise Mizuki characterization',
 'Mizuki is Nightcord''s stylish and playful video creator, known as Amia, whose visual work binds the group''s art together. Beneath their confident love of cute fashion is a history of judgment and a fear that complete visibility will alter precious relationships. Their story centers self-expression, trust, controlled disclosure, and the possibility of acceptance without erasure.',
 'analysis', 'Profile concise character summary', 1.0, strftime('%Y-%m-%dT%H:%M:%fZ','now'), strftime('%Y-%m-%dT%H:%M:%fZ','now'));
